搜索：https://www.yc.ifeng.com/book/search/,{
	"method":"post",
	"body":"query={{key}}"
	}
详情页规则：
a.0@href##.*book\/(\d+).*##http://iyc.ifeng.com/api/books/$1##
目录页规则：
http://iyc.ifeng.com/fhxw/bookshelf/directory,{
  "body": "bookId={{$.bookId}}&chapterNum=0&isNext=1&getNum=10000",
  "method": "POST"
}
章节URL规则：
http://iyc.ifeng.com/api/books/@get:{bid}/chapters/{{$.chapterNum}}/content
正文规则：
$.data.txt
②免费趣小说app：
搜索接口By_遇知：
http://androidapi4.yc.ifeng.com/api/freeClient/book/search,{
  "body": "fr10=6.33.0.06&fr11=1080&fr12=2238&fr13=15164564&fr14=381&fr15=15&page={{page}}&pageCount=50&query={{key}}",
  "method": "POST"
}
书籍列表:
$.data.bookList[*]
书名:
$.name
作者:
$.author
分类:
$.category
最新章节:
$.maxPartName
简介:
$.description
封面:
$.picUrl
详情页规则:
$.scheme##fread\:\/\/interestingnovel\/reader\?readType=0\&bookId=##https://androidapi4.yc.ifeng.com/api/books/?bookid=
*/

//⚠️正文解密By_尐哖：
function m(bArr) {
	i = 0;
	for (i2 = 0; i2 < 2; i2++) {
		i = parseInt(i) + parseInt(bArr[i2] < 0 ? (bArr[i2] + 256) : bArr[i2] << (i2 * 8));
  }
  return i;
}
function decode(bArr){
	length = bArr.length / 2;
  for (i = 0,str = ''; i < length; i++) {
  	i2 = i * 2;
  	b = bArr[i2];
   b2 = bArr[i2 + 1];
   if (b == -1 && b2 == -2) {str += ' ';} 
   else if (b == 13 && b2 == 0) {str += ' ';} 
   else {
     str += String.fromCharCode(((b2 << 8) & 65280) | (b & 255));
   }
  }
  return str;
}

